"""Live-stack sim-to-real `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys


def ci(cell: dict) -> str:
    lo, hi = cell["ci95"]
    return f"{cell['value']:.3f} [{lo:.3f}, {hi:.3f}]"


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    d = r["dataset"]
    faults = sorted(d["faults"])
    out = [
        "<!-- Generated by packages/sati/sati/rca/livereport.py from the live-incidents workflow. "
        "Do not edit by hand. -->\n",
        "# Katyayani on a live cluster — the sim-to-real set (RP-19)\n",
        f"{d['scored']} of {d['planned']} planned fault injections on an eight-service stack running in kind "
        f"({d['errors']} errored and are reported, not dropped). Faults: "
        + ", ".join(f"{f} ({d['faults'][f]})" for f in faults)
        + f". The plan was committed before any run (SHA-256 `{d['plan_sha256'][:12]}…`). Metrics are the "
        "services' own: CPU and memory from each container's cgroup, request rate, error rate and p90 latency. "
        f"Chance is RCA@1 {r['chance']['rca@1']:.3f}, RCA@3 {r['chance']['rca@3']:.3f}.\n",
        "| Ranker | RCA@1 [95% CI] | RCA@3 [95% CI] | " + " | ".join(f"@1 {f}" for f in faults) + " |",
        "|---|---:|---:|" + "---:|" * len(faults),
    ]
    for name, row in r["test"].items():
        out.append(f"| {name} | {ci(row['rca@1'])} | {ci(row['rca@3'])} | "
                   + " | ".join(f"{row['by_fault'][f]['value']:.3f}" for f in faults) + " |")
    t = r["trained_on"]
    out += [
        "",
        f"Kaal training: {t['kaal']['n']:,} synthetic incidents (seed {t['kaal']['seed']}). "
        + (f"RCAEval training: {t['rcaeval_cases']} real cases (RE1 and RE2, all three systems)."
           if t["rcaeval_cases"] else "The RCAEval-trained row was not run."),
        "",
        "## Realism: Kaal against the live stack (RP-18)\n",
        "Share of incidents by how many services went anomalous (peak shift ≥ 2σ), and by propagation depth "
        "(hops from the root to the furthest anomalous caller).\n",
    ]
    for key, title in (("anomalous_services_per_incident", "Anomalous services"), ("propagation_depth", "Depth")):
        live, kaal = r["realism"][key]["live"], r["realism"][key]["kaal"]
        ks = sorted(set(live) | set(kaal), key=int)
        out += [f"| {title} | " + " | ".join(ks) + " |", "|---|" + "---:|" * len(ks)]
        for label, dist in (("live", live), ("Kaal v1", kaal)):
            out.append(f"| {label} | " + " | ".join(f"{dist.get(k, 0):.3f}" for k in ks) + " |")
        out.append("")
    out.append(f"Metric source: {d['metric_source']}. Run time {r['seconds']} s.")
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
